input.content:
:root {
  --bg: #f1f5f9;
  --panel: #ffffff;
  --border: #e2e8f0;
  --text: #0f172a;
  --muted: #64748b;
  --primary: #1d4ed8;
  --primary-soft: #dbeafe;
  --green: #15803d;
  --green-soft: #dcfce7;
  --amber: #b45309;
  --amber-soft: #fef3c7;
  --red: #b91c1c;
  --red-soft: #fee2e2;
  --gray-soft: #f1f5f9;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: -apple-system, "PingFang SC", "Microsoft YaHei", "Segoe UI", sans-serif;
  background: var(--bg);
  color: var(--text);
  font-size: 14px;
}

header.topbar {
  background: linear-gradient(120deg, #0c4a6e, #1d4ed8);
  color: #fff;
  padding: 14px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 8px;
}
header.topbar h1 { margin: 0; font-size: 18px; font-weight: 600; }
header.topbar .sub { font-size: 12px; opacity: .85; }

.layout { display: flex; min-height: calc(100vh - 58px); }
nav.side {
  width: 168px; background: #fff; border-right: 1px solid var(--border);
  padding: 12px 8px; display: flex; flex-direction: column; gap: 4px; flex-shrink: 0;
}
nav.side button {
  text-align: left; border: 0; background: none; padding: 10px 12px; border-radius: 8px;
  cursor: pointer; font-size: 14px; color: var(--text); display: flex; gap: 8px; align-items: center;
}
nav.side button:hover { background: var(--gray-soft); }
nav.side button.active { background: var(--primary-soft); color: var(--primary); font-weight: 600; }
nav.side .badge {
  margin-left: auto; background: var(--red); color: #fff; border-radius: 10px;
  font-size: 11px; padding: 1px 7px;
}

main { flex: 1; padding: 20px 24px; overflow: auto; }

.panel {
  background: var(--panel); border: 1px solid var(--border); border-radius: 12px;
  padding: 18px 20px; margin-bottom: 16px;
}
.panel h2 { margin: 0 0 4px; font-size: 16px; }
.panel .hint { color: var(--muted); font-size: 12px; margin-bottom: 14px; }

.grid { display: grid; gap: 12px; }
.grid.cols-3 { grid-template-columns: repeat(3, 1fr); }
.grid.cols-4 { grid-template-columns: repeat(4, 1fr); }
@media (max-width: 900px) { .grid.cols-3, .grid.cols-4 { grid-template-columns: 1fr 1fr; } }

label.field { display: flex; flex-direction: column; gap: 5px; font-size: 12px; color: var(--muted); }
input, select, textarea {
  border: 1px solid var(--border); border-radius: 8px; padding: 8px 10px; font-size: 14px;
  background: #fff; color: var(--text); outline: none;
}
input:focus, select:focus { border-color: var(--primary); box-shadow: 0 0 0 3px var(--primary-soft); }
input[type="checkbox"] { width: 16px; height: 16px; }

button.btn {
  border: 0; border-radius: 8px; padding: 9px 16px; font-size: 14px; cursor: pointer;
  background: var(--primary); color: #fff; font-weight: 500;
}
button.btn:hover { filter: brightness(1.08); }
button.btn.secondary { background: var(--gray-soft); color: var(--text); border: 1px solid var(--border); }
button.btn.danger { background: var(--red); }
button.btn.green { background: var(--green); }
button.btn.sm { padding: 5px 10px; font-size: 12px; }
button.btn:disabled { opacity: .5; cursor: not-allowed; }

.row { display: flex; gap: 10px; align-items: center; flex-wrap: wrap; }
.row.end { justify-content: flex-end; }

table { width: 100%; border-collapse: collapse; font-size: 13px; }
th, td { text-align: left; padding: 9px 10px; border-bottom: 1px solid var(--border); vertical-align: middle; }
th { color: var(--muted); font-weight: 600; font-size: 12px; white-space: nowrap; }
tr:hover td { background: #f8fafc; }

.tag { display: inline-block; padding: 2px 9px; border-radius: 999px; font-size: 12px; white-space: nowrap; }
.tag.blue { background: var(--primary-soft); color: var(--primary); }
.tag.green { background: var(--green-soft); color: var(--green); }
.tag.amber { background: var(--amber-soft); color: var(--amber); }
.tag.red { background: var(--red-soft); color: var(--red); }
.tag.gray { background: var(--gray-soft); color: var(--muted); }

.toast {
  position: fixed; right: 20px; bottom: 20px; z-index: 50; display: flex; flex-direction: column; gap: 8px;
  max-width: 380px;
}
.toast .item {
  border-radius: 10px; padding: 12px 14px; color: #fff; box-shadow: 0 8px 24px rgba(15,23,42,.18);
  animation: slidein .2s ease;
}
.toast .item.success { background: var(--green); }
.toast .item.error { background: var(--red); }
.toast .item.info { background: #334155; }
.toast .t-title { font-weight: 600; margin-bottom: 2px; }
@keyframes slidein { from { transform: translateY(8px); opacity: 0; } to { transform: none; opacity: 1; } }

.scan-box {
  display: flex; gap: 8px; align-items: center; background: #f8fafc;
  border: 1px dashed #94a3b8; border-radius: 10px; padding: 8px 10px;
}
.scan-box input { flex: 1; border-style: solid; }
.scan-pulse {
  width: 10px; height: 10px; border-radius: 50%; background: #22c55e;
  box-shadow: 0 0 0 0 rgba(34,197,94,.6); animation: pulse 1.6s infinite;
}
@keyframes pulse {
  0% { box-shadow: 0 0 0 0 rgba(34,197,94,.5); }
  70% { box-shadow: 0 0 0 8px rgba(34,197,94,0); }
  100% { box-shadow: 0 0 0 0 rgba(34,197,94,0); }
}

.checks { display: flex; gap: 18px; flex-wrap: wrap; }
.checks label { display: flex; align-items: center; gap: 7px; font-size: 13px; color: var(--text); }

.stat { background: #fff; border: 1px solid var(--border); border-radius: 12px; padding: 14px 16px; }
.stat .n { font-size: 24px; font-weight: 700; }
.stat .l { font-size: 12px; color: var(--muted); }

.detail-meta { display: grid; grid-template-columns: repeat(2, 1fr); gap: 6px 24px; font-size: 13px; }
.detail-meta .k { color: var(--muted); }
.timeline { border-left: 2px solid var(--border); margin-left: 6px; padding-left: 14px; }
.timeline .ev { position: relative; padding: 4px 0; font-size: 13px; }
.timeline .ev::before {
  content: ''; position: absolute; left: -20px; top: 10px; width: 8px; height: 8px;
  border-radius: 50%; background: var(--primary);
}
.timeline .ev .t { color: var(--muted); font-size: 11px; }

.modal-mask {
  position: fixed; inset: 0; background: rgba(15,23,42,.45); z-index: 40;
  display: flex; align-items: center; justify-content: center; padding: 20px;
}
.modal {
  background: #fff; border-radius: 14px; padding: 22px; width: 680px; max-width: 100%;
  max-height: 88vh; overflow: auto;
}
.modal h3 { margin: 0 0 12px; }
.muted { color: var(--muted); }
.mono { font-family: ui-monospace, Menlo, Consolas, monospace; }
.pass { color: var(--green); font-weight: 600; }
.fail { color: var(--red); font-weight: 600; }
.empty { text-align: center; color: var(--muted); padding: 28px 0; }

