import { useState } from 'react';
import { createBox, listBoxes } from '../api';
import { BoxStatusTag, Modal, ScanInput, usePoll, useToast } from '../ui';
import { BoxDetailView } from './BoxDetail';
import { boxDetail } from '../api';
import type { BoxDetail } from '../types';

export function BoxesPage({ openBox }: { openBox?: (id: number) => void }) {
  const toast = useToast();
  const [q, setQ] = useState('');
  const [newCode, setNewCode] = useState('');
  const { data: boxes, reload } = usePoll(() => listBoxes(q), [q], 4000);
  const [detail, setDetail] = useState<BoxDetail | null>(null);

  const showDetail = async (id: number) => {
    const d = await boxDetail(id);
    setDetail(d);
  };

  return (
    <div>
      <div className="panel">
        <h2>保温箱档案与箱号查询</h2>
        <div className="hint">一箱一码，箱号全局唯一；门店可在此查询所收箱子的回收、清洗质检与交接记录。</div>
        <div className="row">
          <ScanInput placeholder="扫描/输入箱号查询，如 BX-1001" buttonText="查询" onScan={(c) => setQ(c)} />
          {q && (
            <button className="btn secondary sm" onClick={() => setQ('')}>清除查询</button>
          )}
          <div style={{ flex: 1 }} />
          <input
            placeholder="新箱建档：输入箱号"
            value={newCode}
            onChange={(e) => setNewCode(e.target.value)}
            style={{ width: 200 }}
          />
          <button
            className="btn"
            onClick={async () => {
              if (!newCode.trim()) return;
              const r = await toast.call(createBox(newCode.trim()), '建档成功', (b) => `箱 ${b.code} 已建档`);
              if (r) {
                setNewCode('');
                reload();
              }
            }}
          >
            新箱建档
          </button>
        </div>
      </div>

      <div className="panel">
        <table>
          <thead>
            <tr>
              <th>箱号</th><th>规格</th><th>状态</th><th>当前位置</th><th>上次使用门店</th><th>在途交接</th><th></th>
            </tr>
          </thead>
          <tbody>
            {(boxes || []).map((b) => (
              <tr key={b.id}>
                <td className="mono">{b.code}</td>
                <td>{b.spec}</td>
                <td><BoxStatusTag status={b.status} /></td>
                <td>{b.currentStore ? b.currentStore.name : <span className="muted">配送中心 DC</span>}</td>
                <td>{b.lastStore?.name ?? <span className="muted">—</span>}</td>
                <td>
                  {b.activeHandover ? (
                    <span className="tag amber">→ {b.activeHandover.targetStore?.name}</span>
                  ) : (
                    <span className="muted">—</span>
                  )}
                </td>
                <td>
                  <button className="btn secondary sm" onClick={() => (openBox ? openBox(b.id) : showDetail(b.id))}>详情</button>
                </td>
              </tr>
            ))}
            {!boxes?.length && (
              <tr><td colSpan={7}><div className="empty">{q ? `未找到箱号 ${q}` : '暂无箱子'}</div></td></tr>
            )}
          </tbody>
        </table>
      </div>

      {detail && !openBox && (
        <Modal title={`箱子详情 · ${detail.box.code}`} onClose={() => setDetail(null)} wide>
          <BoxDetailView data={detail} />
        </Modal>
      )}
    </div>
  );
}

import { useState } from 'react';
import { registerReturn, listBoxes } from '../api';
import { useMeta } from '../meta';
import { BoxStatusTag, usePoll, useToast } from '../ui';

// 门店回收登记
export function ReturnsPage() {
  const toast = useToast();
  const { stores } = useMeta();
  const [boxCode, setBoxCode] = useState('');
  const [storeCode, setStoreCode] = useState(stores[0]?.code || 'S001');
  const [condition, setCondition] = useState('INTACT');
  const [note, setNote] = useState('');
  const { data: boxes, reload } = usePoll(() => listBoxes('', 'RETURNED'), [], 5000);

  const submit = async () => {
    if (!boxCode.trim()) return;
    const r = await toast.call(
      registerReturn({ boxCode: boxCode.trim(), storeCode, condition, note: note || undefined }),
      '回收登记完成',
      (x) => x.message,
    );
    if (r) {
      setBoxCode('');
      setNote('');
      reload();
    }
  };

  return (
    <div>
      <div className="panel">
        <h2>门店回收登记</h2>
        <div className="hint">配送中心回收门店保温箱并登记箱况；箱体破裂直接记录报废去向，不进入清洗。在途箱不能重复回收。</div>
        <div className="grid cols-4">
          <label className="field">
            扫箱号
            <input placeholder="如 BX-1001" value={boxCode} onChange={(e) => setBoxCode(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && submit()} />
          </label>
          <label className="field">
            回收门店
            <select value={storeCode} onChange={(e) => setStoreCode(e.target.value)}>
              {stores.map((s) => <option key={s.id} value={s.code}>{s.name}</option>)}
            </select>
          </label>
          <label className="field">
            箱况
            <select value={condition} onChange={(e) => setCondition(e.target.value)}>
              <option value="INTACT">完好</option>
              <option value="DIRTY">有污渍</option>
              <option value="DAMAGED">箱体破裂</option>
            </select>
          </label>
          <label className="field">
            备注
            <input placeholder="可选" value={note} onChange={(e) => setNote(e.target.value)} />
          </label>
        </div>
        <div className="row end" style={{ marginTop: 12 }}>
          <button className="btn" onClick={submit}>📷 扫码登记回收</button>
        </div>
      </div>

      <div className="panel">
        <h2>已回收到 DC · 待清洗队列</h2>
        <table>
          <thead><tr><th>箱号</th><th>状态</th><th>当前位置</th><th>上次使用门店</th></tr></thead>
          <tbody>
            {(boxes || []).map((b) => (
              <tr key={b.id}>
                <td className="mono">{b.code}</td>
                <td><BoxStatusTag status={b.status} /></td>
                <td>配送中心 DC</td>
                <td>{b.lastStore?.name ?? '—'}</td>
              </tr>
            ))}
            {!boxes?.length && <tr><td colSpan={4}><div className="empty">待清洗队列为空</div></td></tr>}
          </tbody>
        </table>
      </div>
    </div>
  );
}

