    } | null;
  }>;
}

export interface Handover {
  id: number;
  handoverNo: string;
  boxId: number;
  targetStoreId: number;
  driverId: number;
  status: string;
  rejectReason: string | null;
  shippedAt: string;
  closedAt: string | null;
  box?: Box;
  targetStore: Store;
  driver: Staff;
}

