  id: number;
  boxId: number;
  reason: string;
  action: string;
  source: string;
  note: string | null;
  createdAt: string;
  box: Box;
}

export interface AppNotification {
  id: number;
  level: string;
  type: string;
  title: string;
  message: string;
  boxCode: string | null;
  read: boolean;
  createdAt: string;
}

export interface BoxDetail {
  box: Box;
  lastStore: Store | null;
  latestWash: {
    id: number;
    washedAt: string;
    batch: { batchNo: string; washer: Staff };
    inspection: {
      passed: boolean;
      failReasons: string;
      residueFree: boolean;
      dry: boolean;
      intact: boolean;
      inspector: Staff;
      inspectedAt: string;
    } | null;
  } | null;
  activeHandover: Handover | null;
  recentReturns: Array<{
    id: number;
    condition: string;
    note: string | null;
    scannedAt: string;
    store: Store;
  }>;
  box_locEvents?: unknown;
}

