  const dupReturn = await tryPost('/returns', { boxCode: 'BX-1001', storeCode: 'S003', condition: 'INTACT' });
  console.log(dupReturn.status === 409 ? ok(`在途箱回收登记被拒（409）：${dupReturn.data.message}`) : no('在途箱出现了第二个有效位置？'));

