  let after = (await call('/boxes/1')).data;
  console.log(ok(`S002 签收：状态=${after.box.status}，当前位置=${after.box.currentStore.name}，上次使用门店=${after.lastStore.name}，有效交接已清空=${after.box.activeHandoverId === null}`));
